BUILTINS <- c("__LINE__", "__FILE__", "__COUNTER__")
VARIADIC_NAME <- "__VA_ARGS__"
VARIADIC_ERROR <- '"__VA_ARGS__" can only appear in the expansion of a variadic macro'
definition_error <- function(message) stop(structure(list(message = message), class = c("definition_error", "error", "condition")))
macro_get <- function(macros, name) {
  key <- paste0("m:", name)
  if (exists(key, macros, inherits = FALSE)) get(key, macros, inherits = FALSE) else NULL
}
macro_set <- function(macros, name, definition) assign(paste0("m:", name), definition, macros)
macro_remove <- function(macros, name) {
  key <- paste0("m:", name)
  if (exists(key, macros, inherits = FALSE)) rm(list = key, envir = macros)
}
macro_names <- function(macros) vapply(as.list.environment(macros, all.names = TRUE), function(definition) definition$name, character(1L))
signature <- function(definition) {
  if (is.null(definition$parameters)) return(definition$name)
  parameters <- definition$parameters
  if (definition$variadic) parameters[[length(parameters)]] <- "..."
  paste0(definition$name, "(", paste(parameters, collapse = ", "), ")")
}
identical_definition <- function(first, second) {
  identical(first$parameters, second$parameters) && identical(first$variadic, second$variadic) &&
    identical(lapply(first$replacement, function(token) list(token$spelling, token$space)),
              lapply(second$replacement, function(token) list(token$spelling, token$space)))
}
check_macro_name <- function(tokens, directive) {
  if (!length(tokens)) return(paste0("no macro name given in #", directive, " directive"))
  if (tokens[[1L]]$kind != "identifier") return("macro names must be identifiers")
  name <- tokens[[1L]]$spelling
  if (name == "defined") return('"defined" cannot be used as a macro name')
  if (name %in% BUILTINS) return(paste0("cannot ", if (directive == "define") "redefine" else "undefine", ' builtin macro "', name, '"'))
  NULL
}
parse_definition <- function(tokens, position, main_file) {
  error <- check_macro_name(tokens, "define")
  if (!is.null(error)) definition_error(error)
  name <- tokens[[1L]]$spelling
  if (name == VARIADIC_NAME) definition_error(VARIADIC_ERROR)
  parameters <- NULL
  variadic <- FALSE
  index <- 2L
  if (length(tokens) > 1L && tokens[[2L]]$spelling == "(" && !tokens[[2L]]$space) {
    parameters <- character()
    index <- 3L
    if (index > length(tokens)) definition_error("missing ')' in macro parameter list")
    if (tokens[[index]]$spelling == ")") {
      index <- index + 1L
    } else repeat {
      if (index > length(tokens)) definition_error("missing ')' in macro parameter list")
      token <- tokens[[index]]
      if (token$spelling == "...") {
        parameters <- c(parameters, VARIADIC_NAME)
        variadic <- TRUE
      } else if (token$kind == "identifier") {
        if (token$spelling == VARIADIC_NAME) definition_error(VARIADIC_ERROR)
        if (token$spelling %in% parameters) definition_error(paste0('duplicate macro parameter "', token$spelling, '"'))
        parameters <- c(parameters, token$spelling)
      } else {
        definition_error(paste0('expected parameter name, found "', token$spelling, '"'))
      }
      index <- index + 1L
      if (index > length(tokens)) definition_error("missing ')' in macro parameter list")
      following <- tokens[[index]]$spelling
      index <- index + 1L
      if (following == ")") break
      if (variadic) definition_error(paste0('expected \')\' after "...", found "', following, '"'))
      if (following != ",") definition_error(paste0('expected \',\' or \')\', found "', following, '"'))
    }
  }
  replacement <- if (index <= length(tokens)) tokens[seq.int(index, length(tokens))] else list()
  if (length(replacement)) {
    replacement[[1L]] <- token_with(replacement[[1L]], space = FALSE)
    if (replacement[[1L]]$spelling == "##" || replacement[[length(replacement)]]$spelling == "##") definition_error("'##' cannot appear at either end of a macro expansion")
  }
  for (index in seq_along(replacement)) {
    token <- replacement[[index]]
    if (token$kind == "identifier" && token$spelling == VARIADIC_NAME && !variadic) definition_error(VARIADIC_ERROR)
    if (token$spelling == "#" && !is.null(parameters)) {
      if (index == length(replacement) || replacement[[index + 1L]]$kind != "identifier" || !replacement[[index + 1L]]$spelling %in% parameters) definition_error("'#' is not followed by a macro parameter")
    }
  }
  new_record(name = name, parameters = parameters, variadic = variadic, replacement = replacement,
             position = position, main_file = main_file, expanded = 0L, tested = 0L)
}

new_expander <- function(macros, diagnostic) new_record(macros = macros, diagnostic = diagnostic, counter = 0L, builtin_counts = list())
expansion_error <- function(expander, context, token, message) expander$diagnostic(display_position(context, token$line), "error", message)
expand_builtin <- function(expander, token, context) {
  count <- expander$builtin_counts[[token$spelling]]
  expander$builtin_counts[[token$spelling]] <- if (is.null(count)) 1L else count + 1L
  if (token$spelling == "__FILE__") {
    kind <- "string"
    spelling <- paste0('"', context$display_file, '"')
  } else if (token$spelling == "__LINE__") {
    kind <- "number"
    spelling <- integer_text(display_position(context, token$line)$line)
  } else {
    kind <- "number"
    spelling <- integer_text(expander$counter)
    expander$counter <- expander$counter + 1L
  }
  pp_token(kind, spelling, token$line, token$space)
}
collect_arguments <- function(expander, pending, definition, token, context) {
  arguments <- list(list())
  separators <- list()
  nesting <- 0L
  closing <- consumed <- NULL
  cursor <- pending$rest
  index <- 2L
  while (!is.null(cursor)) {
    current <- cursor$token
    cursor <- cursor$rest
    if (current$spelling == ")" && nesting == 0L) {
      closing <- current
      consumed <- index
      break
    }
    if (current$spelling == "," && nesting == 0L) {
      separators[[length(separators) + 1L]] <- current
      arguments[[length(arguments) + 1L]] <- list()
    } else {
      if (current$spelling == "(") nesting <- nesting + 1L
      if (current$spelling == ")") nesting <- nesting - 1L
      last <- length(arguments)
      arguments[[last]][[length(arguments[[last]]) + 1L]] <- current
    }
    index <- index + 1L
  }
  if (is.null(closing)) {
    expansion_error(expander, context, token, paste0('unterminated argument list invoking macro "', definition$name, '"'))
    return(NULL)
  }
  count <- length(arguments)
  fixed <- length(definition$parameters) - as.integer(definition$variadic)
  error <- NULL
  if (!definition$variadic && fixed == 0L && (count != 1L || length(arguments[[1L]]) > 0L)) {
    error <- paste0('macro "', definition$name, '" passed ', count, ' arguments, but takes just 0')
  } else if (count < fixed) {
    error <- paste0('macro "', definition$name, '" requires ', fixed, ' arguments, but only ', count, ' given')
  } else if (count > fixed && !definition$variadic) {
    error <- paste0('macro "', definition$name, '" passed ', count, ' arguments, but takes just ', fixed)
  }
  if (!is.null(error)) {
    expansion_error(expander, context, token, error)
    return(NULL)
  }
  raw <- setNames(head(arguments, fixed), head(definition$parameters, fixed))
  if (definition$variadic) {
    variable <- list()
    if (fixed < count) for (index in seq.int(fixed + 1L, count)) {
      if (index > fixed + 1L) variable[[length(variable) + 1L]] <- separators[[index - 1L]]
      variable <- c(variable, arguments[[index]])
    }
    raw[[VARIADIC_NAME]] <- variable
  }
  list(raw = raw, consumed = consumed, closing = closing)
}
stringize <- function(tokens, sharp) {
  pieces <- character()
  for (index in seq_along(tokens)) {
    token <- tokens[[index]]
    if (index > 1L && token$space) pieces <- c(pieces, " ")
    spelling <- token$spelling
    if (token$kind %in% c("string", "character")) {
      characters <- strsplit(spelling, "", fixed = TRUE)[[1L]]
      spelling <- paste(vapply(characters, function(character) if (character == "\\") "\\\\" else if (character == '"') '\\"' else character, character(1L)), collapse = "")
    }
    pieces <- c(pieces, spelling)
  }
  pp_token("string", paste0('"', paste(pieces, collapse = ""), '"'), sharp$line, sharp$space)
}
paste_tokens <- function(expander, left, right, token, context) {
  if (left$kind == "placemarker") return(list(token_with(right, space = left$space)))
  if (right$kind == "placemarker") return(list(left))
  spelling <- paste0(left$spelling, right$spelling)
  kind <- single_token(spelling)
  if (!is.null(kind)) return(list(pp_token(kind, spelling, left$line, left$space, intersect(left$hide, right$hide))))
  expansion_error(expander, context, token, paste0('pasting "', left$spelling, '" and "', right$spelling, '" does not give a valid preprocessing token'))
  list(left, token_with(right, space = FALSE))
}
substitute <- function(expander, definition, raw, token, hide, context) {
  replacement <- definition$replacement
  items <- list()
  expanded <- new.env(hash = TRUE, parent = emptyenv())
  index <- 1L
  while (index <= length(replacement)) {
    current <- replacement[[index]]
    if (current$spelling == "#" && !is.null(definition$parameters)) {
      parameter <- replacement[[index + 1L]]$spelling
      items[[length(items) + 1L]] <- list(paste = FALSE, tokens = list(stringize(raw[[parameter]], current)))
      index <- index + 2L
      next
    }
    if (current$spelling == "##") {
      item <- list(paste = TRUE, token = current)
    } else if (current$kind == "identifier" && current$spelling %in% names(raw)) {
      adjacent <- (index > 1L && replacement[[index - 1L]]$spelling == "##") || (index < length(replacement) && replacement[[index + 1L]]$spelling == "##")
      if (adjacent) {
        sequence <- raw[[current$spelling]]
      } else {
        if (!exists(current$spelling, expanded, inherits = FALSE)) assign(current$spelling, expand_tokens(expander, raw[[current$spelling]], context), expanded)
        sequence <- get(current$spelling, expanded, inherits = FALSE)
      }
      if (length(sequence)) sequence[[1L]] <- token_with(sequence[[1L]], space = current$space) else sequence <- list(pp_token("placemarker", "", current$line, current$space))
      item <- list(paste = FALSE, tokens = sequence)
    } else {
      item <- list(paste = FALSE, tokens = list(current))
    }
    items[[length(items) + 1L]] <- item
    index <- index + 1L
  }
  pasted <- list()
  index <- 1L
  while (index <= length(items)) {
    item <- items[[index]]
    if (item$paste) {
      left <- pasted[[length(pasted)]]
      pasted <- head(pasted, -1L)
      right_item <- items[[index + 1L]]
      right <- if (right_item$paste) list(right_item$token) else right_item$tokens
      pasted <- c(pasted, paste_tokens(expander, left, right[[1L]], token, context), tail(right, -1L))
      index <- index + 2L
    } else {
      pasted <- c(pasted, item$tokens)
      index <- index + 1L
    }
  }
  result <- list()
  carry_space <- FALSE
  for (current in pasted) {
    if (current$kind == "placemarker") {
      carry_space <- carry_space || current$space
    } else {
      result[[length(result) + 1L]] <- token_with(current, line = token$line, space = current$space || carry_space, hide = union(current$hide, hide))
      carry_space <- FALSE
    }
  }
  if (length(result)) result[[1L]] <- token_with(result[[1L]], space = token$space)
  result
}
expand_tokens <- function(expander, sequence, context) {
  pending <- NULL
  for (current in rev(sequence)) pending <- list(token = current, rest = pending)
  result <- list()
  while (!is.null(pending)) {
    token <- pending$token
    pending <- pending$rest
    if (token$kind != "identifier" || token$spelling %in% token$hide) {
      result[[length(result) + 1L]] <- token
      next
    }
    if (token$spelling %in% BUILTINS) {
      result[[length(result) + 1L]] <- expand_builtin(expander, token, context)
      next
    }
    definition <- macro_get(expander$macros, token$spelling)
    if (is.null(definition) || (!is.null(definition$parameters) && (is.null(pending) || pending$token$spelling != "("))) {
      result[[length(result) + 1L]] <- token
      next
    }
    raw <- list()
    hide <- union(token$hide, definition$name)
    if (!is.null(definition$parameters)) {
      collected <- collect_arguments(expander, pending, definition, token, context)
      if (is.null(collected)) {
        result[[length(result) + 1L]] <- token
        next
      }
      raw <- collected$raw
      for (index in seq_len(collected$consumed)) pending <- pending$rest
      hide <- union(intersect(token$hide, collected$closing$hide), definition$name)
    }
    replacement <- substitute(expander, definition, raw, token, hide, context)
    definition$expanded <- definition$expanded + 1L
    if (!length(replacement) && token$space && !is.null(pending)) pending <- list(token = token_with(pending$token, space = TRUE), rest = pending$rest)
    for (current in rev(replacement)) pending <- list(token = current, rest = pending)
  }
  result
}

LEVELS <- list("||", "&&", "|", "^", "&", c("==", "!="), c("<", ">", "<=", ">="), c("<<", ">>"), c("+", "-"), c("*", "/", "%"))
expression_error <- function(message) stop(structure(list(message = message), class = c("expression_error", "error", "condition")))
parse_digits <- function(text, base) {
  result <- 0
  for (character in utf8ToInt(text)) {
    digit <- if (character <= 57L) character - 48L else if (character <= 70L) character - 55L else character - 87L
    result <- result * base + digit
  }
  result
}
integer_value <- function(spelling) {
  value <- spelling
  for (suffix in c("ll", "LL", "l", "L")) if (endsWith(value, suffix) && nchar(value) > nchar(suffix)) {
    value <- substr(value, 1L, nchar(value) - nchar(suffix))
    break
  }
  if (grepl("^0[xX][0-9a-fA-F]+$", value)) return(parse_digits(substring(value, 3L), 16))
  if (grepl("^0[0-7]*$", value)) return(parse_digits(value, 8))
  if (grepl("^[1-9][0-9]*$", value)) return(parse_digits(value, 10))
  expression_error(paste0('invalid integer constant "', spelling, '"'))
}
character_value <- function(spelling) {
  value <- substr(spelling, 2L, nchar(spelling) - 1L)
  if (nchar(value) == 1L && !value %in% c("'", "\\")) return(as.numeric(utf8ToInt(value)))
  escapes <- setNames(c(10, 9, 92, 39, 34, 0), c("n", "t", "\\", "'", '"', "0"))
  if (nchar(value) == 2L && substr(value, 1L, 1L) == "\\" && substring(value, 2L) %in% names(escapes)) return(escapes[[substring(value, 2L)]])
  expression_error(paste("invalid character constant", spelling))
}
pp_expression <- function(kind, value = NULL, children = list()) list(kind = kind, value = value, children = children)
next_spelling <- function(parser) if (parser$index <= length(parser$tokens)) parser$tokens[[parser$index]]$spelling else NULL
parse_conditional <- function(parser) {
  left <- parse_binary(parser, 1L)
  if (identical(next_spelling(parser), "?")) {
    parser$index <- parser$index + 1L
    first <- parse_conditional(parser)
    if (!identical(next_spelling(parser), ":")) expression_error("'?' without following ':'")
    parser$index <- parser$index + 1L
    last <- parse_conditional(parser)
    left <- pp_expression("conditional", children = list(left, first, last))
  }
  left
}
parse_binary <- function(parser, level) {
  if (level > length(LEVELS)) return(parse_unary(parser))
  left <- parse_binary(parser, level + 1L)
  while (length(next_spelling(parser)) && next_spelling(parser) %in% LEVELS[[level]]) {
    operator <- next_spelling(parser)
    parser$index <- parser$index + 1L
    right <- parse_binary(parser, level + 1L)
    left <- pp_expression("binary", operator, list(left, right))
  }
  left
}
parse_unary <- function(parser) {
  if (length(next_spelling(parser)) && next_spelling(parser) %in% c("+", "-", "!", "~")) {
    operator <- next_spelling(parser)
    parser$index <- parser$index + 1L
    operand <- parse_unary(parser)
    return(pp_expression("unary", operator, list(operand)))
  }
  if (parser$index > length(parser$tokens)) expression_error("expected value at end of expression")
  token <- parser$tokens[[parser$index]]
  parser$index <- parser$index + 1L
  if (token$kind == "number") return(pp_expression("constant", integer_value(token$spelling)))
  if (token$kind == "character") return(pp_expression("constant", character_value(token$spelling)))
  if (token$kind == "identifier") return(pp_expression("identifier", token$spelling))
  if (token$spelling == "(") {
    value <- parse_conditional(parser)
    if (!identical(next_spelling(parser), ")")) expression_error("missing ')' in expression")
    parser$index <- parser$index + 1L
    return(value)
  }
  expression_error(paste0('expected value before "', token$spelling, '"'))
}
parse_expression <- function(tokens, directive) {
  if (!length(tokens)) expression_error(paste0("#", directive, " with no expression"))
  parser <- new_record(tokens = tokens, index = 1L)
  tree <- parse_conditional(parser)
  if (!is.null(next_spelling(parser))) expression_error(paste0('missing binary operator before "', next_spelling(parser), '"'))
  tree
}
bitwise_value <- function(operator, first, second) {
  left <- first %% 4294967296
  right <- second %% 4294967296
  result <- 0
  power <- 1
  for (index in seq_len(32L)) {
    a <- left %% 2
    b <- right %% 2
    bit <- if (operator == "&") a == 1 && b == 1 else if (operator == "|") a == 1 || b == 1 else a != b
    if (bit) result <- result + power
    left <- left %/% 2
    right <- right %/% 2
    power <- power * 2
  }
  if (result >= 2147483648) result - 4294967296 else result
}
binary_value <- function(operator, first, second) {
  if (operator %in% c("/", "%")) {
    if (second == 0) expression_error("division by zero in #if")
    quotient <- abs(first) %/% abs(second)
    if ((first < 0) != (second < 0)) quotient <- -quotient
    return(if (operator == "/") quotient else first - second * quotient)
  }
  if (operator == "+") return(first + second)
  if (operator == "-") return(first - second)
  if (operator == "*") return(first * second)
  if (operator == "<<") return(first * 2 ^ second)
  if (operator == ">>") return(first %/% 2 ^ second)
  if (operator %in% c("&", "|", "^")) return(bitwise_value(operator, first, second))
  as.numeric(switch(operator, "==" = first == second, "!=" = first != second, "<" = first < second,
                    ">" = first > second, "<=" = first <= second, ">=" = first >= second))
}
evaluate_expression <- function(tree, warning) {
  pending <- list(list(operation = "evaluate", item = tree))
  values <- numeric()
  pop_value <- function() {
    value <- tail(values, 1L)
    values <<- head(values, -1L)
    value
  }
  push_value <- function(value) {
    value <- force(value)
    values <<- c(values, if (value == 0) 0 else value)
  }
  command <- function(operation, item = NULL) list(operation = operation, item = item)
  while (length(pending)) {
    next_command <- pending[[length(pending)]]
    pending <- head(pending, -1L)
    operation <- next_command$operation
    item <- next_command$item
    if (operation == "evaluate") {
      kind <- item$kind
      if (kind == "constant") {
        push_value(item$value)
      } else if (kind == "identifier") {
        warning(paste0('identifier "', item$value, '" evaluates to 0'))
        push_value(0)
      } else if (kind == "unary") {
        pending <- c(pending, list(command("unary", item$value), command("evaluate", item$children[[1L]])))
      } else if (kind == "conditional") {
        pending <- c(pending, list(command("choose", item$children[2L:3L]), command("evaluate", item$children[[1L]])))
      } else if (item$value %in% c("&&", "||")) {
        pending <- c(pending, list(command("logical", list(item$value, item$children[[2L]])), command("evaluate", item$children[[1L]])))
      } else {
        pending <- c(pending, list(command("binary", item$value), command("evaluate", item$children[[2L]]), command("evaluate", item$children[[1L]])))
      }
    } else if (operation == "choose") {
      selected <- if (pop_value() != 0) item[[1L]] else item[[2L]]
      pending[[length(pending) + 1L]] <- command("evaluate", selected)
    } else if (operation == "logical") {
      first <- pop_value()
      if ((item[[1L]] == "&&" && first == 0) || (item[[1L]] == "||" && first != 0)) push_value(as.numeric(first != 0)) else pending <- c(pending, list(command("truth"), command("evaluate", item[[2L]])))
    } else if (operation == "truth") {
      push_value(as.numeric(pop_value() != 0))
    } else if (operation == "unary") {
      value <- pop_value()
      push_value(if (item == "+") value else if (item == "-") -value else if (item == "!") as.numeric(value == 0) else -value - 1)
    } else {
      second <- pop_value()
      first <- pop_value()
      push_value(binary_value(item, first, second))
    }
  }
  values[[1L]]
}

STARTS <- c("if", "ifdef", "ifndef")
BRANCHES <- c("elif", "elifdef", "elifndef", "else")
directive_name <- function(tokens) if (length(tokens) >= 2L && tokens[[1L]]$spelling == "#" && tokens[[2L]]$kind == "identifier") tokens[[2L]]$spelling else NULL
detect_guard <- function(lines) {
  nonempty <- lapply(Filter(function(logical) length(logical$tokens) > 0L, lines), function(logical) logical$tokens)
  if (!length(nonempty)) return(NULL)
  first <- nonempty[[1L]]
  last <- nonempty[[length(nonempty)]]
  if (length(first) != 3L || !identical(directive_name(first), "ifndef") || first[[3L]]$kind != "identifier") return(NULL)
  if (length(last) != 2L || !identical(directive_name(last), "endif")) return(NULL)
  depth <- 0L
  for (index in seq_along(nonempty)) {
    name <- directive_name(nonempty[[index]])
    if (length(name) && name %in% BRANCHES && depth == 1L) return(NULL)
    if (length(name) && name %in% STARTS) depth <- depth + 1L else if (identical(name, "endif")) depth <- depth - 1L
    if (depth == 0L && index != length(nonempty)) return(NULL)
  }
  if (depth == 0L) first[[3L]]$spelling else NULL
}
new_include_manager <- function() new_record(files = new.env(hash = TRUE, parent = emptyenv()), order = character())
search_header <- function(name, quoted) {
  paths <- if (quoted) c(name, paste0("include/", name)) else paste0("include/", name)
  for (path in paths) {
    full <- file.path("input", path)
    if (file.exists(full) && !file.info(full)$isdir) return(path)
  }
  NULL
}
load_source <- function(manager, path) {
  if (!exists(path, manager$files, inherits = FALSE)) {
    full <- file.path("input", path)
    contents <- rawToChar(readBin(full, "raw", n = file.info(full)$size))
    lines <- lex_source(contents)
    source <- new_record(path = path, physical_lines = sum(strsplit(contents, "", fixed = TRUE)[[1L]] == "\n"),
                         lines = lines, guard = detect_guard(lines), once = FALSE,
                         entered = 0L, skipped = 0L, output_lines = 0L, skipped_lines = 0L)
    assign(path, source, manager$files)
    manager$order <- c(manager$order, path)
  }
  get(path, manager$files, inherits = FALSE)
}

new_record <- function(...) list2env(list(...), parent = emptyenv())
pp_token <- function(kind, spelling, line, space, hide = character()) list(kind = kind, spelling = spelling, line = line, space = space, hide = hide)
token_with <- function(token, kind = token$kind, spelling = token$spelling, line = token$line, space = token$space, hide = token$hide) pp_token(kind, spelling, line, space, hide)
PUNCTUATORS <- strsplit("... <<= >>= -> ++ -- << >> <= >= == != && || *= /= %= += -= &= ^= |= ## [ ] ( ) { } . & * + - ~ ! / % < > ^ | ? : ; = , #", " ")[[1L]]
identifier_start <- function(character) grepl("^[A-Za-z_]$", character)
digit <- function(character) grepl("^[0-9]$", character)
character_at <- function(text, index) if (index < 1L || index > nchar(text)) "" else substr(text, index, index)
read_token <- function(text, position = 1L, header = FALSE) {
  character <- character_at(text, position)
  if (header && character == "<") {
    suffix <- substr(text, position + 1L, nchar(text))
    closing <- regexpr(">", suffix, fixed = TRUE)[[1L]]
    newline <- regexpr("\n", suffix, fixed = TRUE)[[1L]]
    if (closing > 0L && (newline < 0L || closing < newline)) return(list(kind = "header", spelling = substr(text, position, position + closing), end = position + closing + 1L))
  }
  if (identifier_start(character)) {
    ending <- position + 1L
    while (identifier_start(character_at(text, ending)) || digit(character_at(text, ending))) ending <- ending + 1L
    return(list(kind = "identifier", spelling = substr(text, position, ending - 1L), end = ending))
  }
  if (digit(character) || (character == "." && digit(character_at(text, position + 1L)))) {
    ending <- position + 1L
    while (ending <= nchar(text)) {
      current <- character_at(text, ending)
      if (current %in% c("e", "E", "p", "P") && character_at(text, ending + 1L) %in% c("+", "-")) {
        ending <- ending + 2L
      } else if (identifier_start(current) || digit(current) || current == ".") {
        ending <- ending + 1L
      } else {
        break
      }
    }
    return(list(kind = "number", spelling = substr(text, position, ending - 1L), end = ending))
  }
  if (character %in% c('"', "'")) {
    ending <- position + 1L
    while (ending <= nchar(text) && character_at(text, ending) != "\n") {
      if (character_at(text, ending) == character) return(list(kind = if (character == '"') "string" else "character", spelling = substr(text, position, ending), end = ending + 1L))
      ending <- ending + if (character_at(text, ending) == "\\" && ending < nchar(text) && character_at(text, ending + 1L) != "\n") 2L else 1L
    }
  }
  for (punctuator in PUNCTUATORS) if (startsWith(substring(text, position), punctuator)) return(list(kind = "punctuator", spelling = punctuator, end = position + nchar(punctuator)))
  list(kind = "other", spelling = character, end = position + 1L)
}
splice_lines <- function(text) {
  input <- strsplit(text, "", fixed = TRUE)[[1L]]
  characters <- character(length(input))
  positions <- integer(length(input))
  index <- line <- 1L
  used <- 0L
  while (index <= length(input)) {
    if (input[[index]] == "\\" && index < length(input) && input[[index + 1L]] == "\n") {
      index <- index + 2L
      line <- line + 1L
      next
    }
    used <- used + 1L
    characters[[used]] <- input[[index]]
    positions[[used]] <- line
    if (input[[index]] == "\n") line <- line + 1L
    index <- index + 1L
  }
  list(text = paste(characters[seq_len(used)], collapse = ""), positions = positions[seq_len(used)])
}

scan_tokens <- function(text, positions, start = 1L) {
  lines <- tokens <- list()
  index <- 1L
  spaced <- TRUE
  while (index <= nchar(text)) {
    pair <- substr(text, index, index + 1L)
    if (character_at(text, index) == " ") {
      spaced <- TRUE
      index <- index + 1L
    } else if (character_at(text, index) == "\n") {
      ending <- positions[[index]]
      lines[[length(lines) + 1L]] <- list(tokens = tokens, start = start, end = ending)
      tokens <- list()
      start <- ending + 1L
      spaced <- TRUE
      index <- index + 1L
    } else if (pair == "/*") {
      closing <- regexpr("*/", substring(text, index + 2L), fixed = TRUE)[[1L]]
      index <- if (closing < 0L) nchar(text) + 1L else index + closing + 3L
      spaced <- TRUE
    } else if (pair == "//") {
      closing <- regexpr("\n", substring(text, index + 2L), fixed = TRUE)[[1L]]
      index <- if (closing < 0L) nchar(text) + 1L else index + closing + 1L
      spaced <- TRUE
    } else {
      header <- length(tokens) == 2L && tokens[[1L]]$spelling == "#" && tokens[[2L]]$spelling == "include"
      read <- read_token(text, index, header)
      tokens[[length(tokens) + 1L]] <- pp_token(read$kind, read$spelling, positions[[index]], spaced)
      index <- read$end
      spaced <- FALSE
    }
  }
  if (length(tokens)) lines[[length(lines) + 1L]] <- list(tokens = tokens, start = start, end = tail(positions, 1L))
  lines
}
lex_source <- function(text) {
  spliced <- splice_lines(text)
  scan_tokens(spliced$text, spliced$positions)
}
lex_definition <- function(text, line) {
  text <- paste0(text, "\n")
  lines <- scan_tokens(text, rep(line, nchar(text)), line)
  do.call(c, lapply(lines, function(logical) logical$tokens))
}
render <- function(tokens) {
  pieces <- character()
  for (index in seq_along(tokens)) pieces <- c(pieces, paste0(if (index > 1L && tokens[[index]]$space) " " else "", tokens[[index]]$spelling))
  paste(pieces, collapse = "")
}
single_token <- function(text) {
  if (!nzchar(text) || startsWith(text, "//") || startsWith(text, "/*")) return(NULL)
  read <- read_token(text)
  if (read$end == nchar(text) + 1L) read$kind else NULL
}
integer_text <- function(value) if (value == 0) "0" else sprintf("%.0f", value)

